#ifndef MATERIAL_SHARED_PUBLICATION_H
#define MATERIAL_SHARED_PUBLICATION_H
#include "material_shared_target_integral.h"
namespace shared_target {
struct SerializedPacket {uint64_t epoch=0,target=0;R moment[12]={},error[12]={};};
struct Publication {bool published=false,complete=false,budgets=false,positive=false;Q conversion[12]={},reported_error[12]={};};
static Publication publish(uint64_t epoch,uint64_t target,const S*sum,const Q*remainder,const Q*tolerance,bool all_complete,SerializedPacket&caller){Publication result;result.complete=all_complete;SerializedPacket candidate;candidate.epoch=epoch;candidate.target=target;result.budgets=all_complete;for(int k=0;k<12;k++){candidate.moment[k]=R(sum[k].n);result.conversion[k]=fabsq(Q(candidate.moment[k])-sum[k].n);Q error=sf::add(sf::add(sum[k].e,remainder[k]),result.conversion[k]);candidate.error[k]=nextafterl(R(error),INFINITY);result.reported_error[k]=Q(candidate.error[k]);result.budgets=result.budgets&&finiteq(result.reported_error[k])&&result.reported_error[k]<tolerance[k];}result.positive=all_complete&&Q(candidate.moment[MASS])>result.reported_error[MASS]&&Q(candidate.moment[THERMAL])>result.reported_error[THERMAL];result.published=result.budgets&&result.positive;if(result.published)caller=candidate;return result;}
static bool publication_unit_contract(){S sum[12];Q remainder[12]={},tau[12];for(int k=0;k<12;k++){sum[k]=S(strtoflt128("1.23456789012345678901234567890123e-10",nullptr));tau[k]=1e-50Q;}SerializedPacket caller;caller.epoch=9;caller.target=1234;auto before=caller;auto rejected=publish(1,68526,sum,remainder,tau,true,caller);need(!rejected.published&&!memcmp(&before,&caller,sizeof(caller))&&rejected.conversion[MASS]>tau[MASS],"final R80 conversion must reject even when pre-conversion error is zero");for(auto&q:tau)q=1e-8Q;auto accepted=publish(1,68526,sum,remainder,tau,true,caller);need(accepted.published&&caller.epoch==1&&caller.target==68526,"separate manufactured publication unit fixture");before=caller;auto missing=publish(1,68526,sum,remainder,tau,false,caller);need(!missing.published&&!memcmp(&before,&caller,sizeof(caller)),"missing coverage preserves caller despite small errors");return true;}
}
#endif
